import math


def calculate(left: float, operator: str, right: float) -> float:
    """Calculate one operation, rejecting invalid operators and zero divisors."""
    if operator == "+":
        return left + right
    if operator == "-":
        return left - right
    if operator == "*":
        return left * right
    if operator == "/":
        if right == 0:
            raise ValueError("Cannot divide by zero.")
        return left / right
    raise ValueError("Choose +, -, *, or /.")


def read_number(prompt: str) -> float:
    """Read a finite number, allowing the user to retry invalid input."""
    while True:
        try:
            number = float(input(prompt))
            if math.isfinite(number):
                return number
        except ValueError:
            pass
        print("Please enter a finite number.")


def format_result(result: float) -> str:
    """Format the result according to the specified rules."""
    # Treat negative zero as zero
    if result == 0 or math.isclose(result, 0.0, abs_tol=1e-15):
        return "0"
    # Whole number (no fractional part)
    if result == int(result):
        return str(int(result))
    abs_result = abs(result)
    # Use scientific notation for very large numbers
    if abs_result >= 1e15:
        # 12 significant digits in scientific notation
        return f"{result:.12e}"
    # Otherwise, use up to 12 significant digits, fixed-point
    # Remove trailing zeros and decimal point if not needed
    formatted = f"{result:.12g}"
    # If 'e' in formatted, force fixed-point for |result| < 1e15
    if 'e' in formatted or 'E' in formatted:
        # Use 12 digits after decimal, strip trailing zeros
        formatted = f"{result:.12f}".rstrip('0').rstrip('.')
    return formatted


def main() -> None:
    print("Calculator: +, -, *, / (enter q to quit)")
    try:
        while True:
            operator = input("Operation: ").strip().lower()
            if operator in {"q", "quit", "exit"}:
                break
            if operator not in {"+", "-", "*", "/"}:
                print("Choose +, -, *, or /.")
                continue
            left = read_number("First number: ")
            right = read_number("Second number: ")
            try:
                result = calculate(left, operator, right)
                print(f"Result: {format_result(result)}")
            except ValueError as error:
                print(error)
    except (EOFError, KeyboardInterrupt):
        print()
    print("Goodbye!")


if __name__ == "__main__":
    main()

